"""Generates REPORT.md from results/modified_residue_inventory.json (no number is typed here).

    .venv/bin/python benchmarks/audit/modified_residue_inventory_2026-10-26/make_report.py
"""

import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
d = json.loads((HERE / "results/modified_residue_inventory.json").read_text())
c, col = d["counts"], d["collection"]


def table(rows, head):
    return "\n".join(["| " + " | ".join(head) + " |", "|" + "---|" * len(head)] + ["| " + " | ".join(str(x) for x in r) + " |" for r in rows])


rel_by_file = {}
for r in d["relevant_residues"]:
    rel_by_file.setdefault(r["input_id"], []).append(r)
t1 = table([[f["input_id"], f["sha256"][:12], f["selected_chain"], ", ".join(f["pairs"]), f["polymer_residues_in_selected_chain"], f["modres_records"],
             len(rel_by_file.get(f["input_id"], [])), sum(not r["modres_annotated"] for r in rel_by_file.get(f["input_id"], [])),
             sum(r["adapter_included"] for r in rel_by_file.get(f["input_id"], [])), f["residues_absent_from_adapter_output_in_selected_chain"]] for f in col["files"]],
           ["input", "SHA-256 (first 12)", "chain", "pair:side", "amino-acid-like residue records (N, CA, C) in the chain", "MODRES records", "non-standard residues with backbone atoms (from coordinates)",
            "of these without a MODRES record", "of these read by the adapter", "residue records absent from the adapter output"])
t2 = table([[r["input_id"], f"{r['chain']}:{r['resseq']}{r['icode']}", f"{r['resname']} ({r['record_type']})", f"{r['parent_documented']} ({r['chem_comp'].get('name')})",
             (r["modres"] or {}).get("comment", "none"), ", ".join(a for a, v in r["atoms_observed"].items() if v),
             f"{r['neighbour_backbone']['C_prev_to_N_angstrom']:.2f} / {r['neighbour_backbone']['C_to_N_next_angstrom']:.2f}",
             "yes" if r["adapter_included"] else "no", "; ".join(f"{s['pair_id']}{s['side']}: {'in' if s['in_correspondence'] else 'not in'}" for s in r["study_inclusion"]),
             r["uniprot_index"], f"{r['category']}: {r['category_label']}"] for r in d["relevant_residues"]],
           ["input", "deposited chain:number", "deposited name (record)", "documented parent (component name)", "MODRES", "backbone atoms observed", "C(i-1)-N(i) / C(i)-N(i+1) (Å)",
            "installed adapter includes it", "study correspondence", "reference index (UniProt numbering)", "category"])
t3 = table([[p["pair_id"], "/".join(p["entries"]), p["n_positions"], f"{p['windows_with_values']['3']} / {p['windows_with_values']['4']}",
             f"{p['windows_excluded_by_study_output']['3']} / {p['windows_excluded_by_study_output']['4']}",
             f"{p['windows_touching_a_gap_with_an_observed_unread_modified_residue']['3']} / {p['windows_touching_a_gap_with_an_observed_unread_modified_residue']['4']}",
             f"{p['windows_in_gaps_made_only_of_observed_modified_residues']['3']} / {p['windows_in_gaps_made_only_of_observed_modified_residues']['4']}",
             "yes" if p["gap_links_match_study_exclusions"] else "NO"] for p in d["pairs"]],
           ["pair", "entries", "positions", "windows with values (3-res / 4-res)", "excluded in the study output (3 / 4)", "of these, touching a gap that contains an observed unread modified residue (3 / 4)",
            "of these, gaps made only of observed modified residues, so no unobserved residue is involved (3 / 4)", "recomputed gaps equal the recorded exclusions"])
gaps = [g for p in d['pairs'] for g in p['gaps'] if g['contains_observed_unread_modified_residue']]
gap_note = (f"In each of the {len(gaps)} such gaps the unread modified residue is the only residue between its neighbours ({', '.join(str(len(g['skipped'])) for g in gaps)} skipped residue(s)), and it is observed in both chains of the pair." if gaps and all(len(g['skipped']) == 1 and g['all_skipped_residues_observed_in_both_chains'] for g in gaps) else f"{len(gaps)} such gap(s); see the JSON for their composition.")
text = f"""# Modified-residue coverage inventory of the KIN-PAIR-1 inputs (generated report)

Generated by `make_report.py` from `results/modified_residue_inventory.json`. **Scope: the {col['n_files']} original input files ({col['n_unique_sha256']} unique SHA-256 values; {col['n_pair_slots']} pair slots) of the six KIN-PAIR-1 pairs,
selected chains only; every frequency applies to this local, selected collection, not to kinases generally.** No window metric was computed: windows are counted from the study's
recorded exclusion rows and from the continuity of the deposited coordinates. Phosphorylation annotation is not evidence of functional state or of any effect. KIN-PAIR-1 and its outcome are unchanged.

## Answer

- Non-standard amino acids with backbone atoms found from the **coordinate records** in the selected chains: {c['n_relevant_residues']} (of {col['n_polymer_residue_records_in_selected_chains']} amino-acid-like residue records); {c['n_with_modres']} have a MODRES record and {c['n_without_modres_annotation']} do not (the coordinate scan found none beyond the annotated ones); {len(d['annotated_without_coordinates'])} MODRES annotations without coordinates. Names: {', '.join(c['names'])} (documented components: {', '.join(sorted({r['chem_comp'].get('name') or '?' for r in d['relevant_residues']}))}).
- **The installed adapter omits them.** All {c['n_observed_unread_by_adapter']} are fully observed (N, CA, C, O present, peptide-bonded to both neighbours) and are absent from the adapter's output, because its `protein` selection does not contain the residue name; the study's correspondence, which uses only residues the adapter reads, therefore omits them (category 2, observed residue excluded by the parser). Standard residues were never absent from the adapter output in these chains.
- **Windows prevented from evaluation:** {c['windows_touching_gaps_with_observed_unread_modified_residue']['3']} three-residue and {c['windows_touching_gaps_with_observed_unread_modified_residue']['4']} four-residue windows touch a gap that contains such a residue, out of {c['windows_excluded_by_study_output_total']['3']} and {c['windows_excluded_by_study_output_total']['4']} excluded windows and {c['windows_with_values_total']['3']} and {c['windows_with_values_total']['4']} windows with values in the six pairs. {gap_note}

## Coverage tables

{t1}

*Table 1. Purpose: show, per input file, how many non-standard residues with backbone atoms the coordinate records contain, how many carry a MODRES record, and how many the installed adapter reads. Limitation: selected chains of {col['n_files']} files chosen by the KIN-PAIR-1 rules; not a sample of kinases. Source: `results/modified_residue_inventory.json` (files hash-verified against `kin_pair_1/results/KIN-PAIR-1_selection.json`).*

{t2}

*Table 2. Purpose: the record of each affected residue: deposited identity, documented parent, coordinates, adapter and study inclusion and the exact category. Region: unverified (no verified kinase role mapping exists for these targets); deposited and reference numbering are shown, and no region is inferred from numbers. Limitation: the parent and component name come from the MODRES record and the RCSB chemical component record. Source: same file.*

{t3}

*Table 3. Purpose: quantify the 3- and 4-residue windows involved, per pair, without new scores. A window is touched if it contains a link across a gap that holds an observed unread modified residue. Limitation: counts of windows that overlap (adjacent windows share the same gap); an upper bound on what support could recover, since other conditions (Cα–Cα distance, run length) were not re-evaluated beyond the recorded exclusions. Source: same file and `{d['pairs'][0]['study_outputs'].rsplit('/', 1)[0]}/<pair>/`.*

Other polymer chains in the same files: {'none contains a non-standard residue with backbone atoms' if not any(v for vs in d['other_chains_in_the_same_files'].values() for v in [[c_ for c_ in vs if c_['non_standard_residues_with_backbone']]] if v) else 'see the JSON'}.

## Recommendation

**{d['recommendation']['text']}** Decision rule, fixed in the script before the result was read: {d['decision_rule']}.
Evidence that the adapter drops a name is also in the diagnostic tests (`tests/test_modified_residue_inventory.py`: SEP, TPO and PTR are absent from the real adapter output; MSE and standard residues are read).

If the task is taken (not implemented here), acceptance tests:
1. SYNTHETIC chains with SEP, TPO, PTR (HETATM records) and a standard parent: the residue is read as a position with its Cα; its **deposited name and MODRES parent/annotation are kept** in residues.csv and the manifest, never replaced by the parent name.
2. Chain continuity: C(i-1)-N(i) bonding, numbering adjacency and the 4.2 Å Cα–Cα rule are applied exactly as for standard residues; a modified residue does not bridge a real gap.
3. The two PIM1 pairs gain exactly their previously excluded windows (counts from Table 3) and nothing else; all other pairs' outputs are byte-identical; windows around other gaps stay excluded with their causes.
4. A modified residue without Cα or without peptide bonds stays excluded with a named cause; an unannotated non-standard residue with backbone atoms is reported, not silently read or dropped.
5. Reference checks: κ/τ and local RMSD at the newly included windows against the independent references of KIN-PAIR-1; invariance under rigid motion; the residue-name mismatch policy (`flag`) marks windows with a modified residue.
6. Historical schemas and outputs remain readable and unchanged unless the new behaviour is requested.
"""
(HERE / "REPORT.md").write_text(text)
print("wrote REPORT.md")
